		["Enabled"] = "启用",
		["Enabling reasoning support keeps its level buttons visible in short model pickers. Provider details and the caption compact first; extremely limited keyboard space keeps the levels available through Options."] = "启用推理支持后，在矮小的模型选择器中仍会显示级别按钮。空间不足时先压缩提供商详情与说明文字；键盘空间极小的情况下，级别仍可通过「选项」使用。",
		["Enjoying ProjectUAI?"] = "喜欢 Project UAI 吗？",
		["Enter "] = "输入 ",
