		["Enum type"] = "枚举类型",
		["Error"] = "错误",
		["Every day, model and token count this client has recorded is discarded. The conversations themselves are kept."] = "本客户端记录的每日用量、模型与 Token 计数都会被丢弃，对话本身保留。",
		["Every release this client has shipped, newest first."] = "此客户端发布过的每个版本，最新在前。",
		["Every request and every log line the client has kept, and what it keeps them for."] = "客户端保留的每个请求与日志，以及保留它们的原因。",
		["Every stored fact is deleted."] = "所有已存储的事实都会被删除。",
