		["Path under "] = "路径位于 ",
		["Pause a key without deleting its name or usage, then resume it when needed. Paused keys are skipped in rotation; a paused selected key stays pinned until you resume it or change your selection."] = "可暂停某把密钥而不删除其名称或用量，需要时再恢复。暂停的密钥会跳过轮换；被选中且暂停的密钥会保持固定，直到你恢复它或改选其他密钥。",
		["Pause for a few seconds before continuing, to let something in the game settle or a change take effect."] = "暂停几秒再继续，让游戏中的状态稳定或让改动生效。",
		["Peak hour"] = "高峰时段",
