		["Type to search."] = "输入关键词开始搜索。",
		-- u
		["UAI Bridge desktop app"] = "UAI Bridge 桌面端",
		["UAI Relay checks official releases at startup and every 15 minutes while running, downloads compatible updates automatically, and verifies the APK's hash, package, version and signing certificate."] = "UAI Relay 会在启动时以及运行期间每 15 分钟检查官方发布，自动下载兼容更新，并校验 APK 的哈希、包名、版本与签名证书。",
		["UAI calls only"] = "仅 UAI 调用",
		["UAI is free to use. Optional donations help keep the project and shared free access running. Thank you for using it."] = "UAI 可免费使用。自愿捐赠有助于维持项目与共享免费额度。感谢你的使用。",
